"""Generic release inference with explicit or cached best-teacher references."""
from __future__ import annotations

import argparse
from collections import defaultdict
import json
import logging
from pathlib import Path
import unicodedata

import torch

from hindi_detector.artifacts import write_group
from hindi_detector.corrected_synthesis import sha
from hindi_detector.dual_g2p import DualG2P
from hindi_detector.dual_paired_inference import analyze_pair
from hindi_detector.dual_runtime import PhonePair
from hindi_detector.intrinsic_inference import assign_decisions
from hindi_detector.task_vowel_detector import decisions,load,score
from hindi_detector.word_evidence import WordEvidenceEngine
from scripts.calibrate_asr_gate import audio
from scripts.extract_corrected_training import read_rows

ROOT=Path(__file__).resolve().parents[1]


def text_key(text):return ' '.join(unicodedata.normalize('NFC',text).split())


def reference_qualified(site):
    for values in (site['reference_intrinsic_features'],site['secondary']['reference_intrinsic_features']):
        if not (values[2]<0 and values[8]>-1.5 and values[5]>-1.5 and values[30]==1):return False
    return True


def main():
    parser=argparse.ArgumentParser(description='Find Hindi-compatible vowel changes at Nepali word intervals')
    parser.add_argument('--model',type=Path,default=ROOT/'reports/task_vowel_release_v31/model.pt')
    parser.add_argument('--query',type=Path,required=True);parser.add_argument('--text',required=True)
    parser.add_argument('--reference',type=Path,action='append',default=[],help='Trusted same-text reference; repeat for qualified-reference consensus')
    parser.add_argument('--out',type=Path,required=True);parser.add_argument('--device',choices=['auto','mps','cpu'],default='auto')
    args=parser.parse_args()
    if args.out.exists():raise FileExistsError(args.out)
    networks,state=load(args.model)
    for path,digest in state['code_sha256'].items():
        if sha(ROOT/path)!=digest:raise ValueError('Release dependency changed: '+path)
    identities=[];waves=[]
    query=args.query.resolve(strict=True);digest=sha(query);waves.append(audio(query.parent,{'audio':query.name,'sha256':digest}));identities.append({'role':'query','path':str(query),'sha256':digest,'bytes':query.stat().st_size})
    references=args.reference;reference_mode='explicit_trusted_reference'
    if not references:
        plan=ROOT/'data/swar_teacher_v21';selection=json.loads((plan/'selection.json').read_text());matches=[j for j in selection['jobs'] if text_key(j['text'])==text_key(args.text)]
        receipts={r['id']:r for r in read_rows(plan/'teacher/items.jsonl')}
        if not matches:raise ValueError('No generated same-text reference is cached. Supply --reference or generate verified24-layer teacher references for this text.')
        if len(matches)>2:raise ValueError('Cached reference text is ambiguous across source cases; supply explicit references')
        references=[];reference_mode='cached_verified_24_layer_teacher'
        runtime=json.loads((plan/'teacher/runtime.json').read_text())
        if runtime['loaded_layers']!=24 or runtime['weights_sha256']!='2b4636e3aed0e4f2d035630e504be95fc58f494b690a851a91bfe0dd8299516f':raise ValueError('Cached reference source is wrong')
        for job in matches:
            receipt=receipts[job['id']];path=plan/'teacher'/receipt['audio']
            if receipt['status']!='ok_unreviewed' or sha(path)!=receipt['sha256']:raise ValueError('Cached reference audio identity differs')
            references.append(path)
    for path in references:
        path=path.resolve(strict=True);digest=sha(path);waves.append(audio(path.parent,{'audio':path.name,'sha256':digest}));identities.append({'role':'reference','path':str(path),'sha256':digest,'bytes':path.stat().st_size})
    device=('mps' if torch.backends.mps.is_available() and max(map(len,waves))<=20*16000 else 'cpu') if args.device=='auto' else args.device
    if device=='mps' and max(map(len,waves))>20*16000:raise ValueError('Long inputs require CPU for the entire comparison')
    phonemizer=DualG2P(ROOT);engine=WordEvidenceEngine(ROOT,device=device,pitch_method='dio',temporal_bins=20,retain_frame_evidence=True)
    runtime=PhonePair(ROOT,state,device=device,primary_engine=engine);items=[]
    for samples in waves:
        detail,arrays=engine.analyze(samples,args.text);other=runtime.encode_one(samples,1)
        primary={'detail':detail,'phone_log_probs':arrays['phone_log_probs']}
        secondary={'detail':{**detail,'phone_frame_seconds':len(samples)/16000/len(other)},'phone_log_probs':other}
        items.append((primary,secondary))
    query,secondary_query=items[0];per_reference=[];groups=defaultdict(list)
    for reference_index,(reference,secondary_reference) in enumerate(items[1:]):
        words,sites,x=analyze_pair(query,reference,secondary_query,secondary_reference,phonemizer.word,phonemizer.ipa,engine.vocab,runtime.vocabularies[1])
        if len(x):
            p=score(networks,state,x);assign_decisions(words,sites,p,decisions(state,x,p))
        else:assign_decisions(words,[],[],[])
        for site in sites:
            site['reference_qualified']=reference_qualified(site);site['reference_index']=reference_index
            key=(site['word_ordinal'],site['site']['kind'],site['site']['index'],tuple(site['native_phones']))
            groups[key].append(site)
        per_reference.append({'reference':identities[reference_index+1],'words':words})
    words=[{**w,'sites':[],'actual_hindi_error_probability':None} for w in query['detail']['words']]
    for key,sites in groups.items():
        valid=[s for s in sites if s['reference_qualified']];values={s['decision'] for s in valid}
        decision=next(iter(values)) if len(values)==1 else 'uncertain'
        if not valid:decision='unsupported_reference'
        words[key[0]]['sites'].append({'site':sites[0]['site'],'native_phones':sites[0]['native_phones'],
            'decision':decision,'qualified_references':len(valid),'available_references':len(sites),
            'reference_evidence':sites,'actual_hindi_error_probability':None})
    for ordinal,word in enumerate(words):
        ds={s['decision'] for s in word['sites']}
        word['decision']='strong_vowel_change' if 'strong_vowel_change' in ds else 'uncertain' if ds&{'uncertain','unsupported_reference'} else 'no_strong_vowel_change' if ds else 'untested_site'
        if word['decision']=='strong_vowel_change' and any(not r['words'][ordinal]['sites'] and not r['words'][ordinal]['unavailable_reasons'] for r in per_reference):
            word['decision']='uncertain';word['native_variant_ambiguity']='A reference-selected Native variant has no supported Hindi contrast'
    result={'text':args.text,'model_sha256':sha(args.model),'reference_mode':reference_mode,'encoder_device':device,
        'inputs':identities,'words':words,'per_reference':per_reference,'word_flags':[w['word'] for w in words if w['decision']=='strong_vowel_change'],
        'tracks':query['detail']['tracks'],'seconds':query['detail']['seconds'],'actual_hindi_error_accuracy':None,
        'development_regressions_used_for_release_selection':True,'content_checked_with_asr':False,
        'scope':'Word-local Hindi-compatible vowel evidence relative to qualified same-text Native references; never voice/nationality classification.',
        'limits':['Scores are controlled-change model scores, not calibrated Hindi-error probabilities.',
            'One qualified reference is explicitly weaker than replicated support; conflicting qualified references abstain.',
            'No flag is not a correctness guarantee. Unsupported sounds and ambiguous transcripts remain explicit.',
            'Prosody is diagnostic; Hindi-specific intonation accuracy is not established.']}
    write_group(args.out,{'result.json':result,'source_snapshot.json':[{'path':str(p.relative_to(ROOT)),'sha256':sha(p),'source_utf8':p.read_text()}
        for p in (Path(__file__),ROOT/'hindi_detector/dual_paired_inference.py',ROOT/'hindi_detector/dual_runtime.py',ROOT/'hindi_detector/dual_g2p.py')]},
        'Cold generic release inference on actual audio/text, explicit or cached verified teacher references. '
        'result.json exact inputs/model hashes, per-word/per-reference phonetic evidence, qualifications '
        'and conservative consensus. No fixed-case prediction or word-specific threshold. No raw waveform '
        'or encoder copies; NOT on HF/inherited source/MMS research rights. Current consumer verification '
        'and user inference; review2026-11-09, retain compact result while current model is consumed.',
        ['.venv-indicf5/bin/python -m scripts.detect_nepali_leakage --query WAV --text NEPALI --out NEW [--reference SAME_TEXT_WAV ...]'])
    print(json.dumps({'word_flags':result['word_flags'],'reference_mode':reference_mode,'model_sha256':result['model_sha256']},ensure_ascii=False))


if __name__=='__main__':
    logging.basicConfig(level=logging.INFO)
    try:main()
    except Exception:
        logging.exception('Release inference failed explicitly');raise

"""Join two independently measured backbones for the same phonetic site."""
from __future__ import annotations

import numpy as np

from hindi_detector.dual_paired_vowels import FEATURE_NAMES
from hindi_detector.paired_local_inference import analyze_pair as single_pair


def analyze_pair(query,reference,secondary_query,secondary_reference,word_lookup,ipa,vocabulary,secondary_vocabulary):
    words,sites,features=single_pair(query,reference,word_lookup,ipa,vocabulary)
    other_words,other_sites,other_features=single_pair(secondary_query,secondary_reference,word_lookup,ipa,secondary_vocabulary)
    if [w['word'] for w in words]!=[w['word'] for w in other_words]:raise ValueError('Two probes lost canonical word identity')
    def key(site):return site['word_ordinal'],site['site']['kind'],site['site']['index'],tuple(site['native_phones'])
    lookup={key(s):s for s in other_sites}
    if len(lookup)!=len(other_sites):raise ValueError('Duplicate second-probe phonetic identity')
    retained=[];vectors=[]
    for site in sites:
        other=lookup.get(key(site))
        if other is None:
            words[site['word_ordinal']]['unavailable_reasons'].append('Second probe cannot support the same reference-selected Native variant/site')
            continue
        primary=site['features'];secondary=other['features'];f=np.r_[primary,secondary].astype(np.float32)
        site.update(primary_features=primary,secondary_features=secondary,features=f.tolist(),secondary=other)
        retained.append(site);vectors.append(f)
    for ordinal,word in enumerate(words):word['sites']=[s for s in retained if s['word_ordinal']==ordinal]
    return words,retained,np.stack(vectors) if vectors else np.empty((0,len(FEATURE_NAMES)),np.float32)

"""Pinned local two-phone-model runtime; no hidden downloads or substitutions."""
from __future__ import annotations

import json

import numpy as np
import torch
from transformers import AutoFeatureExtractor,AutoModelForCTC

from hindi_detector.corrected_synthesis import sha


class PhonePair:
    def __init__(self,root,state,device='mps',primary_engine=None):
        if device not in {'cpu','mps'} or device=='mps' and not torch.backends.mps.is_available():raise ValueError('Unavailable phone device')
        self.device=device;self.models=[];self.vocabularies=[]
        inventories=[state['phone_inventory'],state['secondary_phone_inventory']]
        for index,directory in enumerate([root/'models/phoneme_probe',root/'models/phoneme_probe_lv60_v20']):
            actual=json.loads((directory/'inventory.json').read_text())
            if actual!=inventories[index]:raise ValueError('Requested checkpoint inventory differs')
            for member in actual['files']:
                path=directory/member['path']
                if path.stat().st_size!=member['bytes'] or sha(path)!=member['sha256']:raise ValueError('Phone checkpoint bytes changed')
            vocabulary=json.loads((directory/'vocab.json').read_text());self.vocabularies.append(vocabulary)
            if {k:vocabulary[k] for k in ('<pad>','<s>','</s>','<unk>')}!={'<pad>':0,'<s>':1,'</s>':2,'<unk>':3}:raise ValueError('Unexpected phone special IDs')
            if index==0 and primary_engine is not None:
                if primary_engine.phone_inventory!=actual or primary_engine.device!=device:raise ValueError('Shared primary runtime differs')
                extractor,model=primary_engine.extractor,primary_engine.phone
            else:
                extractor=AutoFeatureExtractor.from_pretrained(directory,local_files_only=True)
                model=AutoModelForCTC.from_pretrained(directory,local_files_only=True).eval().to(device)
            if extractor.sampling_rate!=16000 or model.config.pad_token_id!=0:raise ValueError('Unexpected phone input/blank')
            self.models.append((extractor,model))
        torch.set_num_threads(2)

    def encode_one(self,samples,index):
        samples=np.asarray(samples,np.float32)
        if samples.ndim!=1 or not 3200<=len(samples)<=30*16000 or not np.isfinite(samples).all():raise ValueError('Need finite16k mono speech between0.2 and30sec')
        if self.device=='mps' and len(samples)>20*16000:raise ValueError('Long utterance requires whole-group CPU execution')
        extractor,model=self.models[index]
        with torch.inference_mode():
            output=model(**{k:v.to(self.device) for k,v in extractor(samples,sampling_rate=16000,return_tensors='pt').items()})
            lp=output.logits[0].log_softmax(-1).cpu().numpy()
        if lp.ndim!=2 or lp.shape[1]!=len(self.vocabularies[index]) or not np.isfinite(lp).all():raise ValueError('Invalid measured phone posterior')
        return lp

    def encode(self,samples):return [self.encode_one(samples,index) for index in (0,1)]
